import{_ as s,C as r,o as i,c as o,aj as t,G as n}from"./chunks/framework.BwH0p-pt.js";const f=JSON.parse('{"title":"Measurements","description":"","frontmatter":{},"headers":[],"relativePath":"3.0/measurements/index.md","filePath":"3.0/measurements/index.md","lastUpdated":1785836850000}'),d={name:"3.0/measurements/index.md"};function u(l,e,m,h,c,g){const a=r("ImagePopup");return i(),o("div",null,[e[0]||(e[0]=t('<h1 id="measurements" tabindex="-1">Measurements <a class="header-anchor" href="#measurements" aria-label="Permalink to &quot;Measurements&quot;">​</a></h1><p>Products carry physical values — a width in centimeters, a weight in kilograms, a capacity in liters. <strong>Measurements</strong> let you store these values with their unit, so &quot;12 in&quot; and &quot;30.48 cm&quot; mean the same thing everywhere: in the PIM, in your exports, and on every sales channel.</p><p>Without a shared unit system, the same product ends up listed as &quot;2 kg&quot; on one channel and &quot;2000&quot; (grams? pounds?) on another. Measurements keep the number and the unit together, and UnoPim converts between units for you.</p><h2 id="measurement-families" tabindex="-1">Measurement families <a class="header-anchor" href="#measurement-families" aria-label="Permalink to &quot;Measurement families&quot;">​</a></h2><p>A <strong>measurement family</strong> represents one physical quantity — Length, Weight, Area, Volume, Duration, Temperature, and so on. Each family groups the units that measure that quantity: the Length family contains Millimeter, Centimeter, Meter, Inch, Feet, Yard, Mile, and more.</p><p>UnoPim ships with a ready-made set of families covering the common quantities (Length, Weight, Area, Volume, Speed, Pressure, Energy, Power, Temperature, Duration, Frequency, Binary, Packaging, and others), each pre-loaded with its units and conversions. You can use them as they are, extend them, or create your own.</p>',6)),n(a,{src:"/assets/3.0/images/measurements/measurement-families-grid.png",alt:"Measurement Families grid in the UnoPim admin"}),e[1]||(e[1]=t('<h3 id="the-standard-unit" tabindex="-1">The standard unit <a class="header-anchor" href="#the-standard-unit" aria-label="Permalink to &quot;The standard unit&quot;">​</a></h3><p>Every family has one <strong>standard unit</strong> — the reference all other units convert to. For Length it is Meter; for Weight it is Kilogram. When a user enters &quot;12 in&quot;, UnoPim also stores the converted value in the standard unit. That converted value is what makes comparing, filtering and exporting products consistent, even when different users entered values in different units.</p><h3 id="units-and-conversions" tabindex="-1">Units and conversions <a class="header-anchor" href="#units-and-conversions" aria-label="Permalink to &quot;Units and conversions&quot;">​</a></h3><p>Each unit in a family carries a <strong>conversion operation</strong> that turns a value in that unit into the standard unit. A conversion is one or more simple steps — <strong>Multiply</strong>, <strong>Divide</strong>, <strong>Add</strong> or <strong>Subtract</strong> by a value. Inch converts to Meter by multiplying by 0.0254; Fahrenheit converts to Kelvin with a subtract-then-divide chain.</p><p>Because every unit knows its way to the standard unit, UnoPim can express any value in any unit of the same family. Enter a value in inches, and it can come out in centimeters in an export or on a channel.</p><h2 id="managing-families-and-units" tabindex="-1">Managing families and units <a class="header-anchor" href="#managing-families-and-units" aria-label="Permalink to &quot;Managing families and units&quot;">​</a></h2><p>You find measurements under <strong>Catalog → Measurement</strong> in the admin panel. What you can see and change here depends on your role — see <a href="#permissions">Permissions</a> below.</p><h3 id="create-a-measurement-family" tabindex="-1">Create a measurement family <a class="header-anchor" href="#create-a-measurement-family" aria-label="Permalink to &quot;Create a measurement family&quot;">​</a></h3><ol><li>Go to <strong>Catalog → Measurement</strong>.</li><li>Click <strong>Create Measurements</strong>.</li><li>Fill in the family and its first unit:</li></ol><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><strong>Code</strong></td><td>Unique identifier of the family (letters, numbers and underscores). Used in imports, exports and the API.</td></tr><tr><td><strong>Standard Unit Code</strong></td><td>The code of the unit that becomes the family&#39;s reference unit.</td></tr><tr><td><strong>Symbol</strong></td><td>The short symbol shown next to values, e.g. <code>km</code>, <code>m</code>.</td></tr><tr><td><strong>Conversion operation</strong></td><td>The Multiply / Divide / Add / Subtract steps that convert this unit to the standard unit.</td></tr></tbody></table><ol start="4"><li>Click <strong>Save</strong>.</li></ol>',11)),n(a,{src:"/assets/3.0/images/measurements/create-measurement-family.png",alt:"Create Measurements form"}),e[2]||(e[2]=t('<p>After saving, open the family to set its <strong>Label</strong> per locale on the <strong>General</strong> tab. Labels are what users see; codes are what systems use.</p><h3 id="add-or-edit-a-unit" tabindex="-1">Add or edit a unit <a class="header-anchor" href="#add-or-edit-a-unit" aria-label="Permalink to &quot;Add or edit a unit&quot;">​</a></h3><ol><li>Open the family from <strong>Catalog → Measurement</strong>.</li><li>Switch to the <strong>Units</strong> tab and click <strong>Create Units</strong>.</li><li>Enter the unit&#39;s <strong>Code</strong>, <strong>Symbol</strong>, its translated labels, and its <strong>Conversion operation</strong> (an <strong>Operator</strong> and a <strong>Value</strong> per step; click <strong>Add New Operation</strong> for multi-step conversions).</li><li>Click <strong>Save</strong>.</li></ol><p>The units grid shows each unit&#39;s name, code and symbol, and marks which one is the <strong>Standard</strong> unit.</p><div class="tip custom-block"><p class="custom-block-title">A family in use is protected</p><p>Once a measurement family is used by an attribute, its standard unit, unit codes and conversion operations are locked, and the standard unit can never be deleted. This protects product values that were already converted. Add new units at any time — just design codes and conversions carefully before you start using the family on products.</p></div><h2 id="precision-and-decimals" tabindex="-1">Precision and decimals <a class="header-anchor" href="#precision-and-decimals" aria-label="Permalink to &quot;Precision and decimals&quot;">​</a></h2><p>You control how many decimals UnoPim keeps for measurement values under <strong>Configuration → System Settings → Measurement</strong>:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td><strong>Decimal strategy</strong></td><td><strong>Round</strong> keeps the nearest value; <strong>Trim</strong> truncates the extra decimals.</td></tr><tr><td><strong>Amount decimals</strong></td><td>Decimal places kept for the value entered by the user (default 4).</td></tr><tr><td><strong>Base value decimals</strong></td><td>Decimal places kept for the value converted to the standard unit (default 6).</td></tr></tbody></table><p>These settings apply to all measurement values across the catalog.</p><h2 id="measurement-attributes" tabindex="-1">Measurement attributes <a class="header-anchor" href="#measurement-attributes" aria-label="Permalink to &quot;Measurement attributes&quot;">​</a></h2><p>To store a measurement on your products, create an <a href="./../attribute/attribute-input.html">attribute</a> of type <strong>Measurement</strong>. When you create it, you bind it to a <strong>Measurement Family</strong> and pick a default <strong>Measurement Unit</strong>.</p><p>On the product edit page, the attribute shows a value field with a unit selector next to it. Users type the number and pick any unit of the family — one enters &quot;30 in&quot;, another &quot;76.2 cm&quot; — and UnoPim stores both the entered value and its standard-unit equivalent, so the data stays comparable.</p>',12)),n(a,{src:"/assets/3.0/images/measurements/measurement-attribute.png",alt:"Measurement attribute on the product edit page"}),e[3]||(e[3]=t('<p>Measurement attributes also work in product grid filters (equal to, greater than, between, and more) and in bulk editing.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>Access to measurements is controlled by roles, under <strong>Settings → Roles</strong>. A role can be granted or denied:</p><ul><li><strong>Measurement Families</strong> — view, create, edit, delete</li><li><strong>Measurement Units</strong> — view, create, edit, delete</li><li><strong>Measurement</strong> configuration — the precision settings above</li></ul><p>A user without these permissions can still use measurement attributes on products; the permissions only govern who may change the unit system itself.</p><h2 id="measurements-in-imports-exports-and-integrations" tabindex="-1">Measurements in imports, exports and integrations <a class="header-anchor" href="#measurements-in-imports-exports-and-integrations" aria-label="Permalink to &quot;Measurements in imports, exports and integrations&quot;">​</a></h2><p>Measurement values travel with their unit through the whole data pipeline:</p><ul><li><strong>Imports</strong> accept a value with a unit code and validate that the unit belongs to the attribute&#39;s family.</li><li><strong>Exports</strong> include the value and unit, and can deliver values converted to the unit a channel expects.</li><li><strong>Integrations and the API</strong> exchange measurement values the same way, so connected systems always receive an unambiguous number-plus-unit pair.</li></ul>',8))])}const y=s(d,[["render",u]]);export{f as __pageData,y as default};
